from adjudication_io import E,read_rows,write_adjudication
import json
r=json.loads((E/'reader_reports/145_scan023_reviewed.json').read_text())
f={x['box']:x['reading'] for x in read_rows(E/'second/145_scan023_first.tsv')}
b={x['box']:[int(x[k]) for k in ['x0','y0','x1','y1']] for x in read_rows(E/'second/145_scan023_boxes.tsv')}
n=dict(f)
inv=(r'\unsure{inverse|réciproque}','inverse')
oldword=r'\unsure{relati.}';newword=r'\unsure{relati.|relat.}'
oldfactor=r'\deleted{\tau_1\tau_\infty={}}';newfactor=r'\deleted{\unsure{\tau_1}\tau_\infty={}}'
oldidx=r'\tau_{\deleted{\unsure{\infty}}1}';newidx=r'\tau_{\deleted{\unsure{\infty|0}}1}'
n['B01']=f['B01'].replace(*inv)
n['B02']=f['B02'].replace(oldword,newword)
n['B03']=f['B03'].replace(oldfactor,newfactor).replace(oldidx,newidx)
c={
'B01':{'final':n['B01'],'changed':True,'adjudication':'Resolve the word as inverse; retain the header10 and rounded E forms.','ink':'The initial narrow upright has a detached dot and is followed by a shallow n/v course and short e/r/s/e sequence. No descending p or q occurs within this word, excluding réciproque. The small header begins with a hooked descending1 and narrow foot, followed by a closed0; there is no broad lower foot of2. The two group letters have the rounded double-turn E form used elsewhere on the sheet.'},
'B02':{'final':n['B02'],'changed':True,'adjudication':'Retain triangulé pondéré, Malgoire and gén without a stop; broaden the cancelled short form to relati./relat.','ink':'The first quoted word has a descending g, tall l and accented final é. The second has a p descender, low o/n sequence and distinct rising d before its accented ending, excluding profini. Malgoire has the capital M, small a, tall l, descending g and o/i/r/e sequence. Gén ends without a separate point. The cancelled short form exposes r/e/l/t-like strokes and a high point, but the final i stem is entangled with the strike, so relati. and relat. remain possible.'},
'B03':{'final':n['B03'],'changed':True,'adjudication':'Retain all three current loop products; qualify the heavily crossed first old factor and broaden one old index.','ink':'The first cancelled tau’s cap and lower curve are heavily crossed while its lower1 remains visible; the complete tau1 factor is therefore qualified. The next cancelled tau-infinity and equals strokes are clearer. On the live right side the first infinity has two dark current lobes over an old tentative0. The next current1 is a thick upright, while the earlier low trace admits infinity or0. In the second row the current0 is a dark closed oval with a paler former loop extending left; the earlier infinity remains tentative. No complete cyclic pattern is supplied to settle these older layers.'},
'B04':{'use_first':True,'adjudication':'Retain the drawn rising stroke and point beside underlined NB.','ink':'The note has a short rising horizontal stroke with one separate low point near its middle. Both drawings represent that same two-part sign; no additional equal bar or semantic punctuation is established. The NB underline is independent.'},
'B05':{'use_first':True,'adjudication':'Retain un, the live inserted phrase and its attachment before seules.','ink':'The phrase gén. les tau_i, avec les lies above a long guide turning down before seules. Its terminal point after gén and comma after tau_i are clear. After the relation number and dash, the small un has two connected low turns without a separate final e. Hom signature évident occupies the next baseline. The rounded E-tau forms are not upright Latin E shapes.'},
'B06':{'use_first':True,'adjudication':'Retain capital Pi and the four terminal points after(17).','ink':'The group sign has a full horizontal cap and two full-height descending posts, with only a short turn at the right foot; the local capital Pi reading is retained. Décrits has the c/r course, dotted i and tall t. After(17), three closely spaced dots are followed by a more distant fourth point.'},
'B07':{'use_first':True,'adjudication':'Retain the short slightly rising separator stroke.','ink':'The crop contains one unbroken stroke, rising slightly to the right, with no arrowhead, second line or attached label. The independent reading differs only in drawing scale and wrapper; no text change is required.'},
'B08':{'use_first':True,'adjudication':'Retain the unfinished margin with rho on a separate lower line.','ink':'On a les and relations occupy two short baselines. The isolated sign below has a small closed head joining a long descended stem, matching rho; it lacks the tall upper loop and baseline return of a script ell. Nothing follows it, so no missing relation is supplied.'},
'B09':{'use_first':True,'adjudication':'Retain désignera and the single-hatted E of the completion.','ink':'After the descending g, the verb continues with the low n/e/r course and a final a-like turn before the space. The long form désignera is therefore retained. The E immediately following par has one distinct chevron hat; its internal upper curl belongs to the letter. Autom. has a separate terminal point.'},
'B10':{'use_first':True,'adjudication':'Retain the Gamma equality chain, cross sign, doubly hatted E and live inserted à.','ink':'The hatted first Gamma has the same top-and-descending-leg family as the unadorned following Gamma; the lower0,3 pair is separate. The sign between them consists of two short nearly parallel strokes. The product sign has two crossed diagonals, not a third asterisk arm. Both hats above the later E are distinct. The small à has a separate accent and body above the crossed extérieurs; the strike still obscures portions of the old word, so its doubt remains.'},
'B11':{'use_first':True,'adjudication':'Retain the capital Pi forms and double-hatted Gamma.','ink':'Each Pi has a full transverse cap and two substantial descending posts. The Gamma bears two separate chevrons; Aut ext has a lower lac label. The final par Pi-hat is written on the next baseline and lacks supplied terminal punctuation.'},
'B12':{'use_first':True,'adjudication':'Retain the exact-sequence layout and the unresolved small vertical equality/cup sign.','ink':'Four plain arrows join the five terms. The middle E and following Gamma each have two chevron hats, while Pi has one. Below Gamma the small mark has two upright components, but the low bend is too faint to decide whether they join into a cup; the vertical-equality/cup alternatives therefore remain. The lower Aut ext_lac(Pi-hat) is attached beneath Gamma, not a new sequence term.'}}
for x in r['changes']:
 if x['id']=='s023-01':x.update(final='inverse',ink=c['B01']['ink'],confidence='high',crop='crops/second_145_scan023_B01.png',box=b['B01'])
 if x['id']=='s023-04':x.update(final=x['final'].replace(oldword,newword),ink=c['B02']['ink'],crop='crops/second_145_scan023_B02.png',box=b['B02'])
 if x['id']=='s023-06':x.update(final=newidx,ink=c['B03']['ink'],crop='crops/second_145_scan023_B03.png',box=b['B03'])
r['doubts']=[x for x in r['doubts'] if x['place']!='opening line, image ... de Z/2']
for x in r['doubts']:
 if x['place']=='cancelled word before avec':x.update(reading=r'\deleted{'+newword+'}',alternatives=['relati.','relat.'],reason=c['B02']['ink'])
 if x['place']=='(17), first row, second overwritten right-hand index':x.update(reading=r'\deleted{\unsure{\infty|0}}',alternatives=[r'\infty','0'],reason=c['B03']['ink'])
r['doubts'].append({'place':'(17), first cancelled factor at upper left','reading':r'\unsure{\tau_1}','alternatives':[r'\tau_1','partly obscured tau-like factor with lower1'],'confidence':'low','reason':c['B03']['ink']})
for x in r['unlisted_decisions']:
 if x['id']=='U023-01':x.update(reading=r'\deleted{'+newword+'}',ink=c['B02']['ink'],crop='crops/second_145_scan023_B02.png',box=b['B02'])
 if x['id']=='U023-03':x.update(reading=r'\deleted{\unsure{\infty|0}}',ink=c['B03']['ink'],crop='crops/second_145_scan023_B03.png',box=b['B03'])
for x in r['inventory']:
 x['first_words_or_objects']=x['first_words_or_objects'].replace(*inv).replace(oldword,newword).replace(oldfactor,newfactor).replace(oldidx,newidx)
for x in r['abbreviations']:
 if 'relati' in x['form']:x['form']=r'\unsure{relati.|relat.}'
r['notes']=[x.replace('inverse/réciproque','inverse').replace('inverse / réciproque','inverse') for x in r['notes']]
r['notes'].append('Blind audit resolves inverse in the opening line from its dotted initial i and lack of a p/q descender. The short cancelled word remains relati./relat.; the heavily crossed first tau1 factor and one old infinity/0 index in(17) retain explicit qualifications. Current loop products remain unchanged. Triangulé pondéré, Malgoire, the unfinished marginal rho and capital Pi readings are retained from the inspected strokes. The mathematical checks remain unchanged and do not settle any overwritten index.')
r['hand'].append('Scan023: the short cancelled relat(i). has an exposed high point but an obscured final stem. Dark current indices must be distinguished from pale old loops; an established cyclic identity cannot restore their older state. The letter d in pondéré and the g/l/é course of triangulé are visible despite plausible alternative phrases.')
write_adjudication(23,'/root/reader_c',c,[{'old':inv[0],'new':inv[1]}]+[{'old':f[bid],'new':n[bid]} for bid in ['B02','B03']],report_replace={k:r[k] for k in ['changes','doubts','unlisted_decisions','inventory','abbreviations','notes','hand']})
